export const topicsInBranch = (domain, branch) =>
  Object.values(PRACTICE_MANIFEST).filter((m) => m.domain === domain && m.branch === branch);

export const branchHasPractice = (domain, branch) =>
  Object.values(PRACTICE_MANIFEST).some((m) => m.domain === domain && m.branch === branch);
